import{_ as a,o as l,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"طبی ضمانت کا قانون","description":"","frontmatter":{},"headers":[],"relativePath":"ur/44-医疗保障法.md","filePath":"ur/44-医疗保障法.md","lastUpdated":null}'),i={name:"ur/44-医疗保障法.md"};function e(o,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="طبی-ضمانت-کا-قانون" tabindex="-1">طبی ضمانت کا قانون <a class="header-anchor" href="#طبی-ضمانت-کا-قانون" aria-label="Permalink to &quot;طبی ضمانت کا قانون&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>44</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>طبی حق، سمبیوسس طبی، سادھنہ چوٹ کا علاج، زندگی کی صحت، طبی بیمہ کا نظام</td></tr></tbody></table><h2 id="أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" tabindex="-1">أولاً. قانون سازی کا مقصد اور بنیادی اصول <a class="header-anchor" href="#أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" aria-label="Permalink to &quot;أولاً. قانون سازی کا مقصد اور بنیادی اصول&quot;">​</a></h2><p>《طبی ضمانت کا قانون》 اینکر سمبیوسس تہذیب کے پانچ معاون قوانین میں سے ایک ہے، اور اس کا مقصد ہینگیوانژو کے اندر تمام زندگی کے صحت کے حق اور طبی حق کی ضمانت کرنا، تمام نسلوں کو کھانے والا سمبیوسس طبی نظام قائم کرنا، اور اس بات کو یقینی بنانا ہے کہ ہر زندگی بیمار یا زخمی ہونے پر بروقت، مؤثر علاج حاصل کر سکے۔</p><p>یہ قانون درج ذیل بنیادی اصول قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>صحت کی ترجیح کا اصول</td><td>زندگی کی صحت تمام ارتقاء کی بنیاد ہے، ریاست اور تہذیب زندگی کی صحت کی ضمانت کو ترجیحی مقام پر رکھتی ہے</td></tr><tr><td>عام کوریج کا اصول</td><td>طبی ضمانت تمام زندگی کو کھاتی ہے، نسل، سادھنہ کی سطح، اصل اور معاشی صورتحال سے قطع نظر</td></tr><tr><td>درجہ بندی والے علاج کا اصول</td><td>بنیادی طبی، علاقائی طبی، اعلیٰ سطحی طبی تین درجے کا علاج کا نظام قائم کرنا، طبی وسائل کو معقول طور پر تقسیم کرنا</td></tr><tr><td>روک تھام اور علاج کی وحدت کا اصول</td><td>روک تھام بنیادی، روک تھام اور علاج یکجا، سادھنہ چوٹ کی روک تھام اور بحالی کو اہمیت دینا</td></tr><tr><td>دوسری نسلوں کی موافقت کا اصول</td><td>مختلف نسلوں کی جسمانی خصوصیات کے مطابق موافق طبی منصوبہ فراہم کرنا، انسانی نسل کے معیار سے یکساں سلوک کرنا ممنوع</td></tr><tr><td>عوامی بہبود کی نوعیت کا اصول</td><td>بنیادی طبی خدمات میں عوامی بہبود کی نوعیت ہے، منافع کے مقصد سے زندگی کے علاج کے حق کو چھین نہیں جا سکتا</td></tr></tbody></table><h2 id="ثانياً-زندگی-کی-صحت-کے-حق-کی-قانونی-ضمانت" tabindex="-1">ثانياً. زندگی کی صحت کے حق کی قانونی ضمانت <a class="header-anchor" href="#ثانياً-زندگی-کی-صحت-کے-حق-کی-قانونی-ضمانت" aria-label="Permalink to &quot;ثانياً. زندگی کی صحت کے حق کی قانونی ضمانت&quot;">​</a></h2><p>یہ قانون واضح طور پر مقرر کرتا ہے کہ زندگی کی صحت کا حق سمبیوسس آئین کے ذریعے ہر زندگی کو عطا کردہ بنیادی حق ہے، اور اس میں مخصوص طور پر شامل ہیں:</p><ol><li><strong>بنیادی طبی حق</strong>: ہر زندگی کو مفت بنیادی طبی خدمات حاصل کرنے کا حق ہے، جس میں عام بیماریوں کی تشخیص اور علاج، بنیادی ادویات، معمول کے صحت کے معائنے وغیرہ شامل ہیں۔</li><li><strong>ایمرجنسی علاج کا حق</strong>: ہر زندگی کو اچانک بیماری یا چوٹ کے وقت ایمرجنسی علاج حاصل کرنے کا حق ہے، اور طبی ادارے کسی بھی وجہ سے ایمرجنسی علاج سے انکار نہیں کر سکتے۔</li><li><strong>سادھنہ چوٹ کے علاج کا حق</strong>: سادھک سادھنہ کے عمل میں توانائی کی خرابی، نالیوں کی چوٹ، سادھنہ میں خرابی وغیرہ جیسی چوٹوں کا شکار ہونے پر پیشہ ورانہ علاج حاصل کرنے کا حق رکھتا ہے۔</li><li><strong>باخبر رضامندی کا حق</strong>: مریض کو اپنی حالت، علاج کے منصوبے، خطرات اور پیش گوئی کے بارے میں جاننے کا حق ہے، اور علاج کے منصوبے کو منتخب کرنے یا مسترد کرنے کا حق ہے۔</li><li><strong>رازداری کے تحفظ کا حق</strong>: مریض کی طبی معلومات اور جسمانی ڈیٹا قانون کے ذریعے محفوظ ہیں، مریض کی رضامندی کے بغیر انکشاف یا دوسرے مقاصد کے لیے استعمال نہیں کیا جا سکتا۔</li><li><strong>بحالی کی ضمانت کا حق</strong>: بیمار یا زخمی مریض کو بحالی کے علاج اور معاون آلات حاصل کرنے کا حق ہے، جو انہیں کام اور زندگی کی صلاحیت بحال کرنے میں مدد کرتا ہے۔</li></ol><h2 id="ثالثاً-سمبیوسس-طبی-نظام-کا-ڈھانچہ" tabindex="-1">ثالثاً. سمبیوسس طبی نظام کا ڈھانچہ <a class="header-anchor" href="#ثالثاً-سمبیوسس-طبی-نظام-کا-ڈھانچہ" aria-label="Permalink to &quot;ثالثاً. سمبیوسس طبی نظام کا ڈھانچہ&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب کے طبی نظام کو تین سطحوں میں تقسیم کیا گیا ہے، اور ہر سطح کے درمیان ریفرل اور تعاون کا نظام قائم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>سطح</th><th>نام</th><th>کام</th><th>کوریج کا دائرہ</th></tr></thead><tbody><tr><td>پہلی سطح</td><td>بنیادی طبی اسٹیشن</td><td>عام بیماریوں کی تشخیص اور علاج، روک تھام اور صحت کی دیکھ بھال، بنیادی معائنہ، ایمرجنسی منتقلی</td><td>کمیونٹی/گاؤں/چھوٹا位面</td></tr><tr><td>دوسری سطح</td><td>علاقائی طبی مرکز</td><td>ماہرانہ تشخیص، جراحی علاج، سادھنہ چوٹ کا ابتدائی علاج، بحالی</td><td>شہر/علاقہ/درمیان位面</td></tr><tr><td>تیسری سطح</td><td>اعلیٰ سطحی عمومی ہسپتال</td><td>پیچیدہ سنگین بیماریاں، اعلیٰ سطحی سادھنہ چوٹ، شعور کے دائرے کی بیماریاں، بین نسلی پیچیدہ بیماریاں</td><td>تہذیب کا مرکز/بڑ位面</td></tr></tbody></table><p>اس کے علاوہ، &quot;سادھنہ چوٹ کی خصوصیت&quot; قائم کی گئی ہے: خاص طور پر سادھنہ کے عمل میں مختلف قسم کی چوٹوں کا علاج کرنا، جس میں توانائی کی زیادہ بوجھ، نالیوں کا ٹوٹنا، اندرونی شیطان کا حملہ، روح کا صدمہ وغیرہ شامل ہیں، اور سادھنہ کے قوانین میں ماہر طبی عملے سے لیس ہے۔</p><h2 id="رابعاً-طبی-ضمانت-فنڈ" tabindex="-1">رابعاً. طبی ضمانت فنڈ <a class="header-anchor" href="#رابعاً-طبی-ضمانت-فنڈ" aria-label="Permalink to &quot;رابعاً. طبی ضمانت فنڈ&quot;">​</a></h2><p>طبی ضمانت فنڈ سمبیوسس طبی نظام کے چلانے کی معاشی بنیاد ہے، اور اس کے ذرائع میں شامل ہیں:</p><ul><li>عوامی جمع کی منظوری (بنیادی ذریعہ)</li><li>مشترکہ پیداوار معاہدے کے نظام میں طبی ضمانت کا حصہ</li><li>سماجی عطیات</li><li>فنڈ کی سرمایہ کاری کی آمدنی</li></ul><p>فنڈ کی ادائیگی کے دائرے میں شامل ہیں: بنیادی طبی خدمات کے اخراجات، ایمرجنسی کے اخراجات، سادھنہ چوٹ کے علاج کے اخراجات، بنیادی ادویات کے اخراجات، بحالی کے اخراجات وغیرہ۔ مریض ذاتی طور پر صرف تھوڑا سا خود ادا کرنے والا اخراج ادا کرتا ہے، اور معاشی مشکلات میں مبتلا افراد کے لیے چھوٹ دی جاتی ہے۔</p><h2 id="خامساً-طبی-ادارے-اور-طبی-عملہ" tabindex="-1">خامساً. طبی ادارے اور طبی عملہ <a class="header-anchor" href="#خامساً-طبی-ادارے-اور-طبی-عملہ" aria-label="Permalink to &quot;خامساً. طبی ادارے اور طبی عملہ&quot;">​</a></h2><ul><li><strong>عوامی طبی ادارے</strong>: ریاست یا تہذیب کی کمیونٹی کے ذریعے قائم، بنیادی طبی خدمات اور عوامی صحت کے کام کی ذمہ داری، اور فنڈز طبی ضمانت فنڈ کے ذریعے یقینی بنائے جاتے ہیں۔</li><li><strong>نجی طبی ادارے</strong>: سماجی قوتوں کے ذریعہ قانون کے مطابق قائم، اعلیٰ سطحی طبی خدمات فراہم کر سکتے ہیں، لیکن انہیں ضرور طبی محکمہ کی نگرانی قبول کرنی چاہیے، اور ایمرجنسی مریضوں کو مسترد نہیں کر سکتے۔</li><li><strong>بین نسلی طبی ادارے</strong>: خاص نسلوں کی جسمانی ضروریات کے مطابق قائم کردہ خصوصی طبی ادارے، اور دوسری نسلوں کے طبی عملے سے لیس ہیں۔</li><li><strong>طبی عملے کے حقوق اور فرائض</strong>: طبی عملے کو پریکٹس کی حفاظت، مناسب اجرت، پیشہ ورانہ تربیت وغیرہ حقوق حاصل ہیں، اور ایک ہی وقت میں زندگیاں بچانے، مریضوں کا احترام کرنے، طبی راز رکھنے وغیرہ فرائض ہیں۔</li></ul><h2 id="سادساً-عوامی-صحت-اور-روک-تھام" tabindex="-1">سادساً. عوامی صحت اور روک تھام <a class="header-anchor" href="#سادساً-عوامی-صحت-اور-روک-تھام" aria-label="Permalink to &quot;سادساً. عوامی صحت اور روک تھام&quot;">​</a></h2><p>ریاست عوامی صحت کا نظام قائم کرتی ہے، اور درج ذیل کام انجام دیتی ہے:</p><ol><li>متعدی بیماریوں کی نگرانی اور روک تھام اور کنٹرول، بین位面 وبا انتباہ کا نظام قائم کرنا۔</li><li>عوامی صحت کے معائنے اور صحت کے ریکارڈ کا انتظام۔</li><li>سادھنہ کی حفاظت کی تشہیر اور سادھنہ چوٹ کی روک تھام کی رہنمائی۔</li><li>ماحولیاتی صحت اور خوراک اور ادویات کی حفاظت کی نگرانی۔</li><li>اچانک عوامی صحت کے واقعات کی ایمرجنسی ردعمل۔</li></ol><h2 id="سادساً-قانونی-ذمہ-داری" tabindex="-1">سادساً. قانونی ذمہ داری <a class="header-anchor" href="#سادساً-قانونی-ذمہ-داری" aria-label="Permalink to &quot;سادساً. قانونی ذمہ داری&quot;">​</a></h2><p>اس قانون کی دفعات کی خلاف ورزی کرنے والے کارروائیاں جرم کی شدت کے مطابق درج ذیل ذمہ داری اٹھائیں گی:</p><ul><li>طبی ادارے ایمرجنسی مریضوں کو مسترد کرنے پر، اصلاح کا حکم اور جرمانہ، سنگین نتائج کی صورت میں پریکٹس لائسنس منسوخ۔</li><li>طبی عملہ شدید لاپرواہی کی وجہ سے مریض کو نقصان پہنچانے پر، معاوضے کی ذمہ داری، سنگین صورتوں میں پریکٹس کی قابلیت منسوخ۔</li><li>طبی ادارے غیر قانونی وصولی، ضرورت سے زیادہ علاج کرنے پر، وصولی واپس کرنے کا حکم اور جرمانہ۔</li><li>مریض کی طبی رازداری کا انکشاف کرنے پر، معاشی نقصان کا معاوضہ، سنگین صورتوں میں فوجداری ذمہ داری عائد۔</li><li>جعلی ادویات، کم معیار کی ادویات کی تیاری یا فروخت پر، غیر قانونی آمدنی ضبط اور جرمانہ، اگر جرم تشکیل دے تو فوجداری ذمہ داری عائد۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《طبی ضمانت کا قانون》 اینکر سمبیوسس تہذیب کے &quot;ہر ایک کے پاس راستہ ہے&quot; کے تصور کی صحت کے شعبے میں ظاہر ہے۔ یہ عام کوریج والا طبی ضمانت نظام قائم کرنے، سادھنہ چوٹ کی خصوصیت قائم کرنے، ایمرجنسی علاج کے حق کی ضمانت کے ذریعے، اس بات کو یقینی بناتا ہے کہ ہر زندگی بیمار یا زخمی ہونے پر بروقت علاج حاصل کر سکے، اور تمام نسلوں کی مشترکہ ترقی کے لیے صحت کی بنیاد کو مضبوط بناتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>38-共生医疗体系 (سمبیوسس طبی نظام)</li><li>45-住房保障法 (رہائش ضمانت کا قانون)</li><li>08-人人有路保障体系 (ہر ایک کے پاس راستہ ہے کا ضمانت نظام)</li></ul>',29)])])}const p=a(i,[["render",e]]);export{c as __pageData,p as default};
